import{_ as t}from"./chunks/settings-cal.pc.en.Cdbg9NRR.js";import{_ as o}from"./chunks/settings-robot.pc.en.95Z7NI6l.js";import{_ as a,o as i,c as n,a5 as r}from"./chunks/framework.BjM_ivYE.js";const s="/RBQ/images/app/settings-app.pc.en.png",w=JSON.parse('{"title":"Settings","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/settings.md","filePath":"manual/gui/settings.md","lastUpdated":1790654982000}'),d={name:"manual/gui/settings.md"};function c(l,e,h,p,u,b){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Settings come in two sets. Each one lays its sections out as chips across the top — icons only on a phone.</p><ul><li><strong>Robot settings</strong> belong to the selected robot. Open them with the <code>Robot settings</code> tile on the hub. Sections: <code>Calibration</code>, <code>Power</code>, <code>Payload setup</code>, <code>Software update</code>. The title reads <code>Robot</code> with the robot&#39;s name and serial.</li><li><strong>App settings</strong> belong to this device. Open them with the gear button at the top right of the hub or any sub-screen. Sections: <code>Gamepad</code>, <code>App settings</code>. The title reads <code>App</code> with the device and app version.</li></ul><p>On every settings screen the logo at the top left returns to the hub, and the gamepad button next to it goes straight to the control screen. That button works only while a robot is connected or the sim is running.</p><ul><li>Connecting to a robot is done from the robot list on the hub — see <a href="/RBQ/manual/gui/connection.html">Connection</a>.</li><li><code>Gamepad</code> is covered in <a href="/RBQ/manual/gui/gamepad.html">Gamepad</a>.</li><li><code>Software update</code> is covered in <a href="/RBQ/manual/gui/software-update.html">Software Update</a>.</li></ul><p>This page covers the remaining four sections. Operators can use all of them, and rows that need developer mode are marked.</p><h2 id="calibration" tabindex="-1">Calibration <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;Calibration {#calibration}&quot;">​</a></h2><p><img src="'+t+'" alt="Calibration section"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Every calibration here must be run with the robot on flat ground and <strong>stationary</strong>. The IMU and ZMP rows are blocked while the robot is walking, has fallen, or is not reporting its state, and each one asks <code>Run calibration?</code> before it sends the command. <code>Joint home-pose setup</code> has its own confirmation. Do not touch the robot until the calibration has finished.</p></div><h3 id="imu-calibration" tabindex="-1">IMU Calibration <a class="header-anchor" href="#imu-calibration" aria-label="Permalink to &quot;IMU Calibration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><code>Accelerometer calib (ACC)</code></td><td>Field correction of accelerometer drift. Run it <strong>while the robot is sitting</strong>, on level ground; it averages the gravity magnitude for about 2 s and stores the factor.</td></tr><tr><td><code>IMU roll/pitch zero</code></td><td>Makes the current posture the level reference. Takes about half a second — if the robot is tilted when you run it, all later control will be off.</td></tr><tr><td><code>Gyro Bias Calibration</code></td><td>Resets the IMU, waits for the values to settle, then measures the gyro again — about 5 s, <strong>while the robot is sitting</strong>. When it finishes it reports all three axes and whether each one is within the limit. If the bias is still over the limit, hold the robot completely still and run it again.</td></tr></tbody></table><p>Press <code>Run</code>, then confirm <code>Run</code> in the dialog. When a row is blocked, the app tells you why, and if it can clear the block itself, a button appears next to <code>Run</code>: <code>Sit</code> when the robot needs to sit, <code>Stand</code> when it needs to stand, and <code>Auto Start</code> when control is off, which asks first. You get no such button while the robot has fallen, is docking, or is not reporting.</p><p><code>IMU roll/pitch zero</code> shows the current roll and pitch under the level in its dialog. A progress dialog follows while it runs. It ends with <code>Success</code> only when roll and pitch both come back within 1° — if the robot is still tilted, it reads <code>The zero may not have taken effect</code> instead, and you put the robot on flat ground and run it again.</p><h3 id="zmp-calibration" tabindex="-1">ZMP Calibration <a class="header-anchor" href="#zmp-calibration" aria-label="Permalink to &quot;ZMP Calibration&quot;">​</a></h3><p><code>Auto-calibrate ZMP offset</code> finds the center-of-mass offset automatically. The robot must be in STAND on flat ground. It walks one step to square up its legs, then takes up to 60 s to converge. Once the offset converges, the robot saves it on its own and returns to STAND. The panel shows the progress and a completion message.</p><h3 id="joint-calibration" tabindex="-1">Joint Calibration <a class="header-anchor" href="#joint-calibration" aria-label="Permalink to &quot;Joint Calibration&quot;">​</a></h3><p>Re-establishes the leg joints&#39; zeros and offsets. Run it with the robot <strong>sitting</strong>.</p><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td><code>Joint home-pose setup</code></td><td>Hold the home pose with the jig, then store it as the joint zero — four legs</td></tr><tr><td><code>DQ offset calibration</code></td><td><code>Not available yet</code> — the row is reserved and cannot be pressed</td></tr></tbody></table><p><code>Joint home-pose setup</code> opens two dialogs: first the notice (<em>This rewrites the joint zeros — running it without the jig, or with the pose off, leaves the robot booting on wrong zeros</em>), then the per-leg screen. On that screen, pick the joints you want to set; the ones you pick move to the target pose in the 3D view on the left. Fit the jig, hold that pose, and press <code>Save LEG{n} {g} home pose</code>. Writing the zero switches control off (BOARD_RESET), so sit the robot down first — it will collapse if it is standing. The jig is required.</p><p>If the motor boards do not answer, the row is blocked with <em>No communication with the motor boards — turn the 48 V drive (LEGS) power on and run it again</em>; that rail is in <a href="/RBQ/manual/gui/maintenance.html">Maintenance</a>.</p><h3 id="camera-calibration" tabindex="-1">Camera Calibration <a class="header-anchor" href="#camera-calibration" aria-label="Permalink to &quot;Camera Calibration&quot;">​</a></h3><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/manual/gui/developer-mode.html#settings">Developer mode</a>.</p></blockquote><h3 id="docking-calibration" tabindex="-1">Docking calibration <a class="header-anchor" href="#docking-calibration" aria-label="Permalink to &quot;Docking calibration&quot;">​</a></h3><p>The bottom of the Calibration section holds the auto-docking alignment parameters: <code>Offset X (m)</code>, <code>Offset Y (m)</code>, <code>Req Count</code>, <code>Try Count</code>.</p><ul><li><code>Reload</code> re-reads the values from the robot.</li><li><code>Defaults</code> fills the fields with factory defaults — nothing is saved until you press <code>Apply</code>.</li><li><code>Apply</code> writes the values to the robot and reads them back.</li></ul><h2 id="power" tabindex="-1">Power <a class="header-anchor" href="#power" aria-label="Permalink to &quot;Power&quot;">​</a></h2><p>This section switches the auxiliary rails you use day to day. The toggles show the actual PDU state the robot reports, so a change can take about a second to show up. Until the first rail state arrives, the toggles stay disabled.</p><p><strong>12 V toggles</strong> (one tap): <code>Speaker amp (12V)</code>, <code>CCTV (12V)</code>, <code>Thermal (12V)</code>, <code>IR LED (12V)</code>.</p><p><strong>48 V rails</strong> (two-step): <code>ARM · ADDON (48V)</code> and <code>EXTERN (48V)</code> each show the live voltage and a <code>Turn off</code> / <code>Turn on</code> button. Pressing it opens <code>Turn this off?</code> or <code>Turn this on?</code>. Confirm to switch.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>ARM · ADDON (48V)</code> is one PDU port shared by the arm and the add-on. Turning it off also cuts arm power — make sure the arm is stopped first.</p></div><p>Camera, comm, Vision PC, and LEGS (48 V) power, along with LiDAR and system reboot, are not here — switching any of them off breaks the connection or drops the robot. They live in <a href="/RBQ/manual/gui/maintenance.html">Maintenance</a> (developer mode).</p><h2 id="robot-parameters" tabindex="-1">Payload setup <a class="header-anchor" href="#robot-parameters" aria-label="Permalink to &quot;Payload setup {#robot-parameters}&quot;">​</a></h2><p><img src="'+o+'" alt="Robot parameters section"></p><p><code>Payload Configuration</code> describes what is mounted on the robot so the walking dynamics can account for it.</p><ol><li>The robot reports 13 payload slots. Check a slot to mark it as mounted and enter its mass and center of mass (X, Y, Z).</li><li>The footer shows the total mass and combined center of mass, and warns when the total exceeds the limit.</li><li>Press <code>Set Payload</code> and confirm with <code>Apply</code> (<code>Get</code> re-reads the slots from the robot and discards your edits). The confirmation shows the number of mounted slots and the totals; unchecked slots are sent with mass 0. The new values reach the walking dynamics right away, ramped in over one to two seconds.</li></ol><p><code>Help</code> expands a short guide above the table. Robots without the payload slot API show a notice asking for a robot software update instead.</p><h2 id="app-settings" tabindex="-1">App settings <a class="header-anchor" href="#app-settings" aria-label="Permalink to &quot;App settings&quot;">​</a></h2><p><img src="'+s+'" alt="App settings section"></p><p>These settings belong to the app, not the robot.</p><table tabindex="0"><thead><tr><th>Row</th><th>Options</th></tr></thead><tbody><tr><td><code>Theme</code></td><td><code>Dark</code> / <code>Light</code></td></tr><tr><td><code>Language / 언어</code></td><td><code>Korean</code> / <code>English</code> — applies immediately</td></tr><tr><td><code>Joystick sensitivity</code></td><td>Slider — input response curve</td></tr><tr><td><code>Keep screen on</code></td><td>Toggle — keeps the screen awake while controlling</td></tr><tr><td><code>Deadzone</code></td><td>Slider — center range ignored by the joystick</td></tr><tr><td><code>Gyro widget</code></td><td>Toggle — roll/pitch attitude display</td></tr><tr><td><code>Fullscreen</code></td><td>Toggle — browser only</td></tr><tr><td><code>Low-signal warning</code></td><td>Toggle — top warning banner when Wi-Fi signal drops below <code>Warning threshold</code> (slider, shown while enabled)</td></tr><tr><td><code>Warning beep (Notify BEEP)</code></td><td>Toggle — short beep on warnings (web only)</td></tr><tr><td><code>Low battery beep</code></td><td>Toggle — beeps when the robot battery is low; <code>Warning beep (Notify BEEP)</code> must be on (web only)</td></tr><tr><td><code>UI scale</code></td><td>Desktop app only — <code>Auto</code>, 100 % to 200 %</td></tr></tbody></table><h3 id="developer-mode" tabindex="-1">Developer mode <a class="header-anchor" href="#developer-mode" aria-label="Permalink to &quot;Developer mode {#developer-mode}&quot;">​</a></h3><p>The <code>Developer mode</code> toggle is in the profile menu — the round button at the top right, next to the gear. As a guest, turn on <code>Developer mode</code> and enter the password. Turning it off puts you back at the operator level. While you are logged in with an access code (<code>Log in with access code</code> in the same menu) the toggle is not shown, because the account decides the level.</p><p>Developer mode adds the <code>Maintenance</code> tile on the hub, the developer rows above, and the <code>AI motion</code> and <code>Position control</code> groups in the <code>Select motion</code> grid.</p>',43)])])}const y=a(d,[["render",c]]);export{w as __pageData,y as default};
